	private PreparedRestrictionPlan prepareRestrictionPlan(StatementRestrictionSourceProvider provider,
			Supplier<CollectionFactory> collections) {
		// Legacy context variables have their own output-domain rules, including the physical null context.
		if (provider == null || statementPattern.getContextVar() != null) {
			return null;
		}
		RestrictionLayout layout = new RestrictionLayout(statementPatternForMetrics.getBindingNames(), context);
		var sourcePlan = provider.prepareStatementRestriction(statementPatternForMetrics, context, layout);
		if (sourcePlan == null) {
			return null;
		}
		int subjectSlot = lookupSlot(statementPattern.getSubjectVar(), layout);
		int predicateSlot = lookupSlot(statementPattern.getPredicateVar(), layout);
		int objectSlot = lookupSlot(statementPattern.getObjectVar(), layout);
		Set<String> seekNames = new LinkedHashSet<>();
		for (int slot : new int[] { subjectSlot, predicateSlot, objectSlot }) {
			if (slot >= 0) {
				seekNames.add(layout.name(slot));
			}
		}
		return new PreparedRestrictionPlan(
				new RestrictionBlueprint("statement/original-answer-seek", RestrictionBlueprint.Realization.STABLE),
				layout, context, seekNames, (input, owner) -> {
					var view = sourcePlan.open(owner);
					return view != null && (view.source() == tripleSource || view.source() == provider)
							? PreparedRestrictionPlan.iteratorInvocation(
									frame -> evaluateRestricted(input, frame, subjectSlot, predicateSlot, objectSlot))
							: RestrictionCompiler.replayInvocation(this, input, collections,
									tripleSource.getValueCapturer(),
									statementPatternForMetrics);
				});
	}

	private static int lookupSlot(Var variable, RestrictionLayout layout) {
		return variable == null || variable.hasValue() ? -1 : layout.slot(variable.getName());
	}

	private CloseableIteration<BindingSet> evaluateRestricted(BindingSet bindings, RestrictionFrame frame,
			int subjectSlot, int predicateSlot, int objectSlot) {
		if (frame.isUnrestricted()) {
			return evaluate(bindings);
		}
		if (emptyGraph || unboundTest.test(bindings)
				|| subjectSlot >= 0 && frame.unboundOnly(subjectSlot)
				|| predicateSlot >= 0 && frame.unboundOnly(predicateSlot)
				|| objectSlot >= 0 && frame.unboundOnly(objectSlot)) {
			return QueryEvaluationStep.EMPTY_ITERATION;
		}
		BindingSet prepared = prepareBindings(bindings);
		Value originalSubject = getSubjectVar.apply(prepared);
		Value originalPredicate = getPredicateVar.apply(prepared);
		Value originalObject = getObjectVar.apply(prepared);
		Value requestedSubject = lookupValue(frame, subjectSlot);
		Value requestedPredicate = lookupValue(frame, predicateSlot);
		Value requestedObject = lookupValue(frame, objectSlot);
		if (incompatible(originalSubject, requestedSubject) || incompatible(originalPredicate, requestedPredicate)
				|| incompatible(originalObject, requestedObject)) {
			return QueryEvaluationStep.EMPTY_ITERATION;
		}
		Value subject = operand(originalSubject, requestedSubject);
		Value predicate = operand(originalPredicate, requestedPredicate);
		Value object = operand(originalObject, requestedObject);
		if (subject != null && !(subject instanceof Resource) || predicate != null && !(predicate instanceof IRI)) {
			return QueryEvaluationStep.EMPTY_ITERATION;
		}
		if (subject == originalSubject && predicate == originalPredicate && object == originalObject) {
			return RestrictionCompiler.residual(evaluate(bindings), frame);
		}
		Resource[] contexts = contextSup.apply(null);
		if (contexts == null) {
			return QueryEvaluationStep.EMPTY_ITERATION;
		}
		CloseableIteration<? extends Statement> iteration = null;
		try {
			iteration = openStatements((Resource) subject, (IRI) predicate, object, contexts);
			// An original repeated-variable equality can still be required even when physical keys filled its
			// positions. Ask the existing checks using the original operands, not the synthesized lookup values.
			iteration = handleFilter(contexts, (Resource) originalSubject, (IRI) originalPredicate, originalObject,
					iteration);
			CloseableIteration<BindingSet> rows = prepared.isEmpty()
					? new ConvertStatementToBindingSetIterator(iteration, getConvertStatementConverter(), context)
					: new JoinStatementWithBindingSetIterator(iteration, getConverter(), prepared, context);
			return RestrictionCompiler.residual(rows, frame);
		} catch (RuntimeException | Error failure) {
			ExternalValuePreparation.closeWithSuppressed(iteration, failure);
			throw failure;
		}
	}

	private static Value lookupValue(RestrictionFrame frame, int slot) {
		Value requested = slot < 0 ? null : frame.value(slot);
		// A local statement index does not certify endpoint-response blank-node identity.
		return RemoteBNode.containsRemoteIdentity(requested) ? null : requested;
	}

	private static boolean incompatible(Value original, Value requested) {
		return original != null && requested != null && !RestrictionFrame.sameTerm(original, requested);
	}

	private Value operand(Value original, Value requested) {
		if (original != null || requested == null) {
			return original;
		}
		return valuePreparer == null ? requested : valuePreparer.apply(requested);
	}

	private CloseableIteration<? extends Statement> openStatements(Resource subject, IRI predicate, Value object,
			Resource[] contexts) {
		return openStatements(subject, predicate, object, contexts, null);
	}

	private CloseableIteration<? extends Statement> openStatements(Resource subject, IRI predicate, Value object,
			Resource[] contexts, StatementFieldSelection.Demand demand) {
		incrementIndexLookupCount();
		CloseableIteration<? extends Statement> statements;
		if (order != null) {
			statements = tripleSource.getStatements(order, subject, predicate, object, contexts);
		} else if (demand != null) {
			statements = tripleSource.getStatementsForEvaluation(demand, subject, predicate, object, contexts);
		} else {
			statements = tripleSource.getStatements(subject, predicate, object, contexts);
		}
		try {
			if (statements instanceof IndexReportingIterator reporting) {
				String indexName = reporting.getIndexName();
				statementPattern.setIndexName(indexName);
				statementPatternForMetrics.setIndexName(indexName);
			}
			return statements;
		} catch (Throwable failure) {
			ExternalValuePreparation.closeWithSuppressed(statements, failure);
			throw failure;
		}
	}

	@Override
	public CloseableIteration<BindingSet> evaluate(BindingSet bindings) {
		if (emptyGraph) {
			return QueryEvaluationStep.EMPTY_ITERATION;
		} else if (bindings.isEmpty()) {
			ConvertStatementToBindingSetIterator iteration = getIteration();
			if (iteration == null) {
				return QueryEvaluationStep.EMPTY_ITERATION;
			}
			return iteration;

		} else if (unboundTest.test(bindings)) {
			// the variable must remain unbound for this solution see
			// https://www.w3.org/TR/sparql11-query/#assignment
			return QueryEvaluationStep.EMPTY_ITERATION;
		} else {
			CloseableIteration<BindingSet> iteration = getIteration(prepareBindings(bindings));
			if (iteration == null) {
				return QueryEvaluationStep.EMPTY_ITERATION;
			}
			return iteration;
		}
	}

	/** Prepare the immediate projection's private scan without changing the standalone or restricted step. */
	@InternalUseOnly
	public QueryEvaluationStep forProjection(Projection projection) {
		if (!canSelectProjection(projection)) {
			return this;
		}
		Set<String> sources = new LinkedHashSet<>();
		projection.getProjectionElemList().getElements().forEach(element -> sources.add(element.getName()));
		boolean omitSubject = canOmit(normalizedSubjectVar, sources);
		boolean omitPredicate = canOmit(normalizedPredicateVar, sources);
		boolean omitObject = canOmit(normalizedObjectVar, sources);
		int omitted = (omitSubject ? StatementFieldSelection.SUBJECT : 0)
				| (omitPredicate ? StatementFieldSelection.PREDICATE : 0)
				| (omitObject ? StatementFieldSelection.OBJECT : 0);
		if (omitted == 0) {
			return this;
		}

		var projectedConverter = preservePreboundValues(makeConvertStatementConverter(context,
				omitSubject ? null : normalizedSubjectVar, omitPredicate ? null : normalizedPredicateVar,
				omitObject ? null : normalizedObjectVar, normalizedContextVar));
		var demand = new StatementFieldSelection.Demand(omitted);
		return bindings -> {
			if (bindings != EmptyBindingSet.getInstance() || ScopedUnionInput.tracksClearedSiblingInputs()) {
				return evaluate(bindings);
			}
			var iteration = getIteration(demand, projectedConverter);
			return iteration == null ? QueryEvaluationStep.EMPTY_ITERATION : iteration;
		};
	}

	private boolean canSelectProjection(Projection projection) {
		return getClass() == StatementPatternQueryEvaluationStep.class
				&& projection.getArg() == statementPatternForMetrics && order == null && !emptyGraph
				&& context.canOmitUnusedStatementBindings() && context.getActiveGraph() == null
				&& projection.getInheritedGraphParameter() == null && projection.getProjectionContext() == null;
	}

	/** The private empty-input scan creates a separate row containing exactly these identity bindings. */
	@InternalUseOnly
	public boolean emitsIdentityProjection(Projection projection) {
		if (!canSelectProjection(projection) || context.indexedBindingLayout() == null
				|| normalizedContextVar != null || statementPattern.getScope() != Scope.DEFAULT_CONTEXTS) {
			return false;
		}

		Set<String> selected = new LinkedHashSet<>();
		for (ProjectionElem element : projection.getProjectionElemList().getElements()) {
			String source = element.getName();
			if (!element.getProjectionAlias().orElse(source).equals(source) || !selected.add(source)) {
				return false;
			}
		}

		Set<String> emitted = new LinkedHashSet<>();
		for (Var variable : new Var[] { normalizedSubjectVar, normalizedPredicateVar, normalizedObjectVar }) {
			if (variable != null && !variable.isConstant() && !canOmit(variable, selected)) {
				emitted.add(variable.getName());
			}
		}
		return selected.equals(emitted);
	}

	private boolean canOmit(Var variable, Set<String> sources) {
		if (variable == null || variable.hasValue() || variable.isConstant() || sources.contains(variable.getName())) {
			return false;
		}
		// Repeated variables may be read by the statement equality filter even without a projected binding.
		int occurrences = 0;
		for (Var operand : statementPattern.getVarList()) {
			if (operand.getName().equals(variable.getName())) {
				occurrences++;
			}
		}
		return occurrences == 1;
	}

	/**
	 * Conversion creates a fresh mutable result for every statement, so callers may extend the result in place. A
	 * direct lookup can return the caller's input bindings when conversion is unnecessary.
	 */
	static boolean ownsBindingSets(CloseableIteration<BindingSet> iteration) {
		return iteration instanceof ConvertStatementToBindingSetIterator
				|| iteration instanceof JoinStatementWithBindingSetIterator
				|| iteration instanceof DirectLookupBindingSetIteration directLookup && directLookup.converter != null;
	}

	private CloseableIteration<BindingSet> getIteration(BindingSet bindings) {
		final Value contextValue = getContextVar != null ? getContextVar.apply(bindings) : null;

		Resource[] contexts = contextSup.apply(contextValue);
		if (contexts == null) {
			return null;
		}

		// Check that the subject is a Resource and the predicate can be an IRI
		// if not we can't return any value.

		Value subject = getSubjectVar != null ? getSubjectVar.apply(bindings) : null;
		if (subject != null && !subject.isResource()) {
			return null;
		}

		Value predicate = getPredicateVar != null ? getPredicateVar.apply(bindings) : null;
		if (predicate != null && !predicate.isIRI()) {
			return null;
		}

		Value object = getObjectVar != null ? getObjectVar.apply(bindings) : null;
		DirectLookupKey directLookupKey = getDirectLookupKey((Resource) subject, (IRI) predicate, object, contexts);
		boolean reuseBindings = directLookupKey != null
				&& canReuseBindingsWithoutConversion(bindings, contextValue, subject, predicate, object);
		List<Statement> cachedDirectLookup = getCachedDirectLookup(directLookupKey);
		if (cachedDirectLookup != null) {
			if (cachedDirectLookup.isEmpty()) {
				return null;
			}
			if (reuseBindings) {
				return new RepeatedBindingSetIteration(cachedDirectLookup.size(), bindings);
			}
			return new JoinStatementWithBindingSetIterator(
					new CloseableIteratorIteration<>(cachedDirectLookup.iterator()),
					getConverter(), bindings, context);
		}

		CloseableIteration<? extends Statement> iteration = null;
		try {
			iteration = openStatements((Resource) subject, (IRI) predicate, object, contexts);

			if (iteration instanceof EmptyIteration) {
				putCachedDirectLookup(directLookupKey, List.of());
				return null;
			}

			iteration = handleFilter(contexts, (Resource) subject, (IRI) predicate, object, iteration);
			if (directLookupKey != null) {
				return new DirectLookupBindingSetIteration(directLookupKey, iteration, bindings,
						reuseBindings ? null : getConverter());
			}

			return new JoinStatementWithBindingSetIterator(iteration, getConverter(), bindings, context);
		} catch (Throwable t) {
			ExternalValuePreparation.closeWithSuppressed(iteration, t);
			if (t instanceof InterruptedException) {
				Thread.currentThread().interrupt();
			}
			throw new QueryEvaluationException(t);
		}
	}

	@Experimental
	public boolean hasStatement(BindingSet bindings) {
		if (emptyGraph) {
			return false;
		}
		if (unboundTest.test(bindings)) {
			// the variable must remain unbound for this solution see
			// https://www.w3.org/TR/sparql11-query/#assignment
			return false;
		}

		final Value contextValue = getContextVar != null ? getContextVar.apply(bindings) : null;
		Resource[] contexts = contextSup.apply(contextValue);
		if (contexts == null) {
			return false;
		}

		Value subject = getSubjectVar != null ? getSubjectVar.apply(bindings) : null;
		if (subject != null && !subject.isResource()) {
			return false;
		}

		Value predicate = getPredicateVar != null ? getPredicateVar.apply(bindings) : null;
		if (predicate != null && !predicate.isIRI()) {
			return false;
		}

		Value object = getObjectVar != null ? getObjectVar.apply(bindings) : null;
		DirectLookupKey directLookupKey = getDirectLookupKey((Resource) subject, (IRI) predicate, object, contexts);
		List<Statement> cachedDirectLookup = getCachedDirectLookup(directLookupKey);
		if (cachedDirectLookup != null) {
			return !cachedDirectLookup.isEmpty();
		}

		try {
			incrementIndexLookupCount();
			Predicate<Statement> filter = filterContextOrEqualVariables(statementPattern, (Resource) subject,
					(IRI) predicate, object, contexts);
			if (filter == null) {
				boolean hasStatement = tripleSource.hasStatements((Resource) subject, (IRI) predicate, object,
						contexts);
				if (!hasStatement) {
					putCachedDirectLookup(directLookupKey, List.of());
				}
				return hasStatement;
			}

			CloseableIteration<? extends Statement> iteration = null;
			try {
				iteration = tripleSource.getStatements((Resource) subject, (IRI) predicate, object, contexts);
				iteration = handleFilter(contexts, (Resource) subject, (IRI) predicate, object, iteration);
				return iteration.hasNext();
			} finally {
				if (iteration != null) {
					iteration.close();
				}
			}
		} catch (Throwable t) {
			if (t instanceof InterruptedException) {
				Thread.currentThread().interrupt();
			}
			throw new QueryEvaluationException(t);
		}
	}

	private DirectLookupKey getDirectLookupKey(Resource subject, IRI predicate, Value object, Resource[] contexts) {
		if (order != null || subject == null || predicate == null || object == null) {
			return null;
		}
		return new DirectLookupKey(subject, predicate, object, contexts);
	}

	private boolean canReuseBindingsWithoutConversion(BindingSet bindings, Value contextValue, Value subject,
			Value predicate, Value object) {
		return alreadyBoundOrConstant(bindings, normalizedSubjectVar, subject)
				&& alreadyBoundOrConstant(bindings, normalizedPredicateVar, predicate)
				&& alreadyBoundOrConstant(bindings, normalizedObjectVar, object)
				&& alreadyBoundOrConstant(bindings, normalizedContextVar, contextValue);
	}

	private static boolean alreadyBoundOrConstant(BindingSet bindings, Var var, Value value) {
		if (var == null || var.isConstant()) {
			return true;
		}
		return value != null && (var.hasValue() ? bindings.getValue(var.getName()) == value
				: bindings.hasBinding(var.getName()));
	}

	private List<Statement> getCachedDirectLookup(DirectLookupKey directLookupKey) {
		if (directLookupKey == null) {
			return null;
		}
		Map<DirectLookupKey, List<Statement>> cache = directLookupCache;
		if (cache == null) {
			return null;
		}
		synchronized (cache) {
			return cache.get(directLookupKey);
		}
	}

	private void putCachedDirectLookup(DirectLookupKey directLookupKey, List<Statement> statements) {
		if (directLookupKey == null) {
			return;
		}
		Map<DirectLookupKey, List<Statement>> cache = getDirectLookupCache();
		synchronized (cache) {
			cache.put(directLookupKey, statements);
		}
	}

	private Map<DirectLookupKey, List<Statement>> getDirectLookupCache() {
		Map<DirectLookupKey, List<Statement>> cache = directLookupCache;
		if (cache == null) {
			synchronized (this) {
				cache = directLookupCache;
				if (cache == null) {
					cache = new LinkedHashMap<>(DIRECT_LOOKUP_CACHE_MAX_ENTRIES + 1, 0.75f, true) {

						@Override
						protected boolean removeEldestEntry(Map.Entry<DirectLookupKey, List<Statement>> eldest) {
							return size() > DIRECT_LOOKUP_CACHE_MAX_ENTRIES;
						}
					};
					directLookupCache = cache;
				}
			}
		}
		return cache;
	}

	private ConvertStatementToBindingSetIterator getIteration() {
		return getIteration(null, null);
	}

	private ConvertStatementToBindingSetIterator getIteration(StatementFieldSelection.Demand demand,
			BiConsumer<MutableBindingSet, Statement> projectedConverter) {
		Var contextVar = statementPattern.getContextVar();
		Resource[] contexts = contextSup.apply(contextVar != null ? contextVar.getValue() : null);

		if (contexts == null) {
			return null;
		}

		Value subject = statementPattern.getSubjectVar().getValue();

		if (subject != null && !subject.isResource()) {
			return null;
		}

		Value predicate = statementPattern.getPredicateVar().getValue();

		if (predicate != null && !predicate.isIRI()) {
			return null;
		}

		Value object = statementPattern.getObjectVar().getValue();

		CloseableIteration<? extends Statement> iteration = null;
		try {
			iteration = openStatements((Resource) subject, (IRI) predicate, object, contexts, demand);

			if (iteration instanceof EmptyIteration) {
				return null;
			}
			iteration = handleFilter(contexts, (Resource) subject, (IRI) predicate, object, iteration);

			// Return an iterator that converts the statements to var bindings
			return new ConvertStatementToBindingSetIterator(iteration,
					projectedConverter == null ? getConvertStatementConverter() : projectedConverter, context);
		} catch (Throwable t) {
			ExternalValuePreparation.closeWithSuppressed(iteration, t);
			if (t instanceof InterruptedException) {
				Thread.currentThread().interrupt();
			}
			throw new QueryEvaluationException(t);
		}
	}

	private BiConsumer<MutableBindingSet, Statement> getConverter() {
		BiConsumer<MutableBindingSet, Statement> localConverter = converter;
		if (localConverter == null) {
			synchronized (this) {
				localConverter = converter;
				if (localConverter == null) {
					localConverter = preservePreboundValues(
							makeConverter(context, normalizedSubjectVar, normalizedPredicateVar,
									normalizedObjectVar, normalizedContextVar));
					converter = localConverter;
				}
			}
		}
		return localConverter;
	}

	private BiConsumer<MutableBindingSet, Statement> getConvertStatementConverter() {
		BiConsumer<MutableBindingSet, Statement> localConverter = convertStatementConverter;
		if (localConverter == null) {
			synchronized (this) {
				localConverter = convertStatementConverter;
				if (localConverter == null) {
					localConverter = preservePreboundValues(makeConvertStatementConverter(context, normalizedSubjectVar,
							normalizedPredicateVar, normalizedObjectVar, normalizedContextVar));
					convertStatementConverter = localConverter;
				}
			}
		}
		return localConverter;
	}

	private BiConsumer<MutableBindingSet, Statement> preservePreboundValues(
			BiConsumer<MutableBindingSet, Statement> converter) {
		List<Consumer<MutableBindingSet>> originalValues = new ArrayList<>(4);
		for (Var variable : new Var[] { normalizedSubjectVar, normalizedPredicateVar,
				normalizedObjectVar, normalizedContextVar }) {
			if (variable != null && variable.hasValue() && !variable.isConstant()) {
				BiConsumer<Value, MutableBindingSet> setter = context.setBinding(variable.getName());
				Value original = variable.getValue();
				originalValues.add(row -> setter.accept(original, row));
			}
		}
		if (originalValues.isEmpty()) {
			return converter;
		}
		return (row, statement) -> {
			converter.accept(row, statement);
			// Optimizer-inlined bindings retain their captured values and authority, even with an empty input row.
			for (int i = 0; i < originalValues.size(); i++) {
				originalValues.get(i).accept(row);
			}
		};
	}

	private CloseableIteration<? extends Statement> handleFilter(Resource[] contexts,
			Resource subject, IRI predicate, Value object,
			CloseableIteration<? extends Statement> iteration) {

		Predicate<Statement> filter = filterContextOrEqualVariables(statementPattern, subject, predicate, object,
				contexts);

		if (filter != null) {
			// Only if there is filter code to execute do we make this filter iteration.
			return new MetricsReportingFilterIteration(iteration, filter);
		} else {
			return iteration;
		}
	}

	/**
	 * Generate a predicate that tests for Named contexts are matched by retrieving all statements from the store and
	 * filtering out the statements that do not have a context. Or the same variable might have been used multiple times
	 * in this StatementPattern, verify value equality in those cases.
	 */
	protected static Predicate<Statement> filterContextOrEqualVariables(StatementPattern statementPattern,
			Value subjValue, Value predValue, Value objValue, Resource[] contexts) {
		Predicate<Statement> filter = null;
		if (contexts.length == 0 && statementPattern.getScope() == Scope.NAMED_CONTEXTS) {
			filter = st -> st.getContext() != null;
		}
		return filterSameVariable(statementPattern, subjValue, predValue, objValue, filter);
	}

	/**
	 * Build one predicate that filters the statements for ?s ?p ?s cases. But only generates code that is actually
	 * needed else returns null.
	 */
	private static Predicate<Statement> filterSameVariable(StatementPattern statementPattern, Value subjValue,
			Value predValue, Value objValue, Predicate<Statement> filter) {

		Var subjVar = statementPattern.getSubjectVar();
		Var predVar = statementPattern.getPredicateVar();
		Var objVar = statementPattern.getObjectVar();
		Var conVar = statementPattern.getContextVar();

		if (subjVar != null && subjValue == null) {
			boolean subEqPredVar = subjVar.equals(predVar);
			boolean subEqObjVar = subjVar.equals(objVar);
			boolean subEqConVar = subjVar.equals(conVar);
			if (subEqPredVar || subEqObjVar || subEqConVar) {
				filter = andThen(filter, subjectVariableHasEquals(subEqPredVar, subEqObjVar, subEqConVar));
			}
		}

		if (predVar != null && predValue == null) {
			boolean predEqObjVar = predVar.equals(objVar);
			boolean predEqConVar = predVar.equals(conVar);
			if (predEqObjVar || predEqConVar) {
				filter = andThen(filter, predicateVariableHasEquals(predEqObjVar, predEqConVar));
			}
		}

		if (objVar != null && objValue == null) {
			boolean objEqConVar = objVar.equals(conVar);
			if (objEqConVar) {
				filter = andThen(filter, st -> {
					Value obj = st.getObject();
					Resource context = st.getContext();
					return obj.equals(context);
				});
			}
		}

		return filter;
	}

	private static Predicate<Statement> predicateVariableHasEquals(boolean predEqObjVar, boolean predEqConVar) {
		Predicate<Statement> eq = null;
		if (predEqObjVar) {
			eq = st -> st.getPredicate().equals(st.getObject());
		}
		if (predEqConVar) {
			eq = andThen(eq, st -> st.getPredicate().equals(st.getContext()));
		}
		return eq;
	}

	private static Predicate<Statement> subjectVariableHasEquals(boolean subEqPredVar, boolean subEqObjVar,
			boolean subEqConVar) {
		Predicate<Statement> eq = null;
		if (subEqPredVar) {
			eq = st -> st.getSubject().equals(st.getPredicate());
		}
		if (subEqObjVar) {
			eq = andThen(eq, st -> st.getSubject().equals(st.getObject()));
		}
		if (subEqConVar) {
			eq = andThen(eq, st -> st.getSubject().equals(st.getContext()));
		}
		return eq;
	}

	/**
	 * @return the contexts that are valid for this statement pattern or null
	 */
	protected static Function<Value, Resource[]> extractContextsFromDatasets(Var contextVar, boolean emptyGraph,
			Set<? extends Resource> graphs) {

		if (emptyGraph) {
			return RETURN_NULL_VALUE_RESOURCE_ARRAY;
		}

		if (graphs == null || graphs.isEmpty()) {
			// store default behaviour
			return StatementPatternQueryEvaluationStep::contextsGivenContextVal;
		} else {
			Resource[] filled = fillContextsFromDatasSetGraphs(graphs);
			// if contextVar is null contextValue must always be null;
			if (contextVar == null) {
				return contextValue -> filled;
			} else {
				return contextValue -> {
					if (contextValue != null) {
						if ((contextValue.isIRI() || contextValue.isBNode()) && graphs.contains(contextValue)) {
							return new Resource[] { (Resource) contextValue };
						} else {
							// Statement pattern specifies a context that is not part of
							// the dataset
							return null;
						}
					} else {
						return filled;
					}
				};
			}
		}
	}

	private static Resource[] contextsGivenContextVal(Value contextValue) {
		if (contextValue != null) {
			if (RDF4J.NIL.equals(contextValue) || SESAME.NIL.equals(contextValue)) {
				return DEFAULT_CONTEXT;
			} else if (contextValue.isIRI() || contextValue.isBNode()) {
				return new Resource[] { (Resource) contextValue };
			} else {
				return null;
			}
		}
		/*
		 * TODO activate this to have an exclusive (rather than inclusive) interpretation of the default graph in SPARQL
		 * querying. else if (statementPattern.getScope() == Scope.DEFAULT_CONTEXTS ) { contexts = new Resource[] {
		 * (Resource)null }; }
		 */
		else {
			return ALL_CONTEXT;
		}
	}

	private static Resource[] fillContextsFromDatasSetGraphs(Set<? extends Resource> graphs) {
		Resource[] contexts = new Resource[graphs.size()];
		int i = 0;
		for (Resource graph : graphs) {
			Resource context = null;
			if (!(RDF4J.NIL.equals(graph) || SESAME.NIL.equals(graph))) {
				context = graph;
			}
			contexts[i++] = context;
		}
		return contexts;
	}

	private void incrementIndexLookupCount() {
		if (!statementPatternForMetrics.isRuntimeTelemetryEnabled() && !statementPattern.isRuntimeTelemetryEnabled()) {
			return;
		}
		long next = statementPatternForMetrics
				.incrementLongMetricActual(TelemetryMetricNames.INDEX_LOOKUP_COUNT_ACTUAL);
		if (next < 0) {
			next = Math.max(0L, statementPattern.getLongMetricActual(TelemetryMetricNames.INDEX_LOOKUP_COUNT_ACTUAL))
					+ 1L;
		}
		statementPattern.setLongMetricActual(TelemetryMetricNames.INDEX_LOOKUP_COUNT_ACTUAL, next);
	}

	private static final class DirectLookupKey {

		private final Resource subject;
		private final IRI predicate;
		private final Value object;
		private final Resource[] contexts;
		private final int hashCode;

		private DirectLookupKey(Resource subject, IRI predicate, Value object, Resource[] contexts) {
			this.subject = subject;
			this.predicate = predicate;
			this.object = object;
			this.contexts = contexts.clone();
			int result = System.identityHashCode(subject);
			result = 31 * result + System.identityHashCode(predicate);
			result = 31 * result + System.identityHashCode(object);
			result = 31 * result + identityHashCode(this.contexts);
			hashCode = result;
		}

		@Override
		public boolean equals(Object other) {
			if (this == other) {
				return true;
			}
			if (!(other instanceof DirectLookupKey)) {
				return false;
			}
			DirectLookupKey that = (DirectLookupKey) other;
			return subject == that.subject
					&& predicate == that.predicate
					&& object == that.object
					&& identityEquals(contexts, that.contexts);
		}

		@Override
		public int hashCode() {
			return hashCode;
		}

		private static int identityHashCode(Resource[] contexts) {
			int result = 1;
			for (Resource context : contexts) {
				result = 31 * result + System.identityHashCode(context);
			}
			return result;
		}

		private static boolean identityEquals(Resource[] left, Resource[] right) {
			if (left.length != right.length) {
				return false;
			}
			for (int i = 0; i < left.length; i++) {
				if (left[i] != right[i]) {
					return false;
				}
			}
			return true;
		}
	}

	/**
	 * Converts statements into the required bindingsets. A lot of work is done in the constructor and then uses
	 * invokedynamic code with lambdas for the actual conversion.
	 * <p>
	 * This allows avoiding of significant work during the iteration. Which pays of if the iteration is long, otherwise
	 * it of course is an unneeded expense.
	 */
	private static final class ConvertStatementToBindingSetIterator
			implements CloseableIteration<BindingSet>, IndexReportingIterator, CooperativeCancellation,
			BufferedIteration {

		private final BiConsumer<MutableBindingSet, Statement> converter;
		private final QueryEvaluationContext context;
		private final CloseableIteration<? extends Statement> iteration;
		private boolean closed = false;

		@Override
		public boolean requestCancellation() {
			return !closed && CooperativeCancellation.forward(iteration);
		}

		private ConvertStatementToBindingSetIterator(
				CloseableIteration<? extends Statement> iteration,
				BiConsumer<MutableBindingSet, Statement> converter, QueryEvaluationContext context) {
			assert iteration != null;
			this.iteration = iteration;
			this.converter = converter;
			this.context = context;
		}

		@Override
		public IntSupplier bufferedRowsSource() {
			return BufferedIteration.bufferedRowsSource(iteration);
		}

		private BindingSet convert(Statement st) {
			MutableBindingSet made = context.createBindingSet();
			converter.accept(made, st);
			return made;
		}

		@Override
		public boolean hasNext() throws QueryEvaluationException {
			return iteration.hasNext();
		}

		@Override
		public BindingSet next() throws QueryEvaluationException {
			return convert(iteration.next());
		}

		@Override
		public void remove() throws QueryEvaluationException {
			iteration.remove();
		}

		@Override
		public void close() throws QueryEvaluationException {
			if (!closed) {
				closed = true;
				iteration.close();
			}
		}

		@Override
		public void seek(Value minValue, boolean minInclusive, Value maxValue, boolean maxInclusive) {
			// the statement order component of the wrapped iteration is the join variable this iteration is
			// ordered on, so the bounds translate directly
			if (!closed) {
				iteration.seek(minValue, minInclusive, maxValue, maxInclusive);
			}
		}

		@Override
		public boolean supportsSeek() {
			return !closed && iteration.supportsSeek();
		}

		@Override
		public String getIndexName() {
			IndexReportingIterator metrics = indexReporter();
			return metrics == null ? "" : metrics.getIndexName();
		}

		@Override
		public long getSourceRowsScannedActual() {
			IndexReportingIterator metrics = indexReporter();
			return metrics == null ? -1 : metrics.getSourceRowsScannedActual();
		}

		@Override
		public long getSourceRowsMatchedActual() {
			IndexReportingIterator metrics = indexReporter();
			return metrics == null ? -1 : metrics.getSourceRowsMatchedActual();
		}

		@Override
		public long getSourceRowsFilteredActual() {
			IndexReportingIterator metrics = indexReporter();
			return metrics == null ? -1 : metrics.getSourceRowsFilteredActual();
		}

		private IndexReportingIterator indexReporter() {
			return iteration instanceof IndexReportingIterator ? (IndexReportingIterator) iteration : null;
		}
	}

	private static final class JoinStatementWithBindingSetIterator
			implements CloseableIteration<BindingSet>, IndexReportingIterator, CooperativeCancellation {

		private final BiConsumer<MutableBindingSet, Statement> converter;
		private final QueryEvaluationContext context;
		private final BindingSet bindings;
		private final CloseableIteration<? extends Statement> iteration;
		private boolean closed = false;

		@Override
		public boolean requestCancellation() {
			return !closed && CooperativeCancellation.forward(iteration);
		}

		private JoinStatementWithBindingSetIterator(
				CloseableIteration<? extends Statement> iteration,
				BiConsumer<MutableBindingSet, Statement> converter, BindingSet bindings,
				QueryEvaluationContext context) {
			assert iteration != null;
			this.iteration = iteration;
			assert !bindings.isEmpty();
			this.converter = converter;
			this.context = context;
			this.bindings = bindings;

		}

		private BindingSet convert(Statement st) {
			MutableBindingSet made = context.createBindingSet(bindings);
			converter.accept(made, st);
			return made;
		}

		@Override
		public boolean hasNext() throws QueryEvaluationException {
			return iteration.hasNext();
		}

		@Override
		public BindingSet next() throws QueryEvaluationException {
			return convert(iteration.next());
		}

		@Override
		public void remove() throws QueryEvaluationException {
			iteration.remove();
		}

		@Override
		public void close() throws QueryEvaluationException {
			if (!closed) {
				closed = true;
				iteration.close();
			}
		}

		@Override
		public void seek(Value minValue, boolean minInclusive, Value maxValue, boolean maxInclusive) {
			// the statement order component of the wrapped iteration is the join variable this iteration is
			// ordered on, so the bounds translate directly
			if (!closed) {
				iteration.seek(minValue, minInclusive, maxValue, maxInclusive);
			}
		}

		@Override
		public boolean supportsSeek() {
			return !closed && iteration.supportsSeek();
		}

		@Override
		public String getIndexName() {
			IndexReportingIterator metrics = indexReporter();
			return metrics == null ? "" : metrics.getIndexName();
		}

		@Override
		public long getSourceRowsScannedActual() {
			IndexReportingIterator metrics = indexReporter();
			return metrics == null ? -1 : metrics.getSourceRowsScannedActual();
		}

		@Override
		public long getSourceRowsMatchedActual() {
			IndexReportingIterator metrics = indexReporter();
			return metrics == null ? -1 : metrics.getSourceRowsMatchedActual();
		}

		@Override
		public long getSourceRowsFilteredActual() {
			IndexReportingIterator metrics = indexReporter();
			return metrics == null ? -1 : metrics.getSourceRowsFilteredActual();
		}

		private IndexReportingIterator indexReporter() {
			return iteration instanceof IndexReportingIterator ? (IndexReportingIterator) iteration : null;
		}
	}

	private final class DirectLookupBindingSetIteration extends AbstractCloseableIteration<BindingSet>
			implements IndexReportingIterator, CooperativeCancellation {

		private final DirectLookupKey key;
		private final CloseableIteration<? extends Statement> source;
		private final IndexReportingIterator indexReporter;
		private final BindingSet bindings;
		private final BiConsumer<MutableBindingSet, Statement> converter;
		private List<Statement> cacheCandidate = List.of();
		private volatile boolean cancellationRequested;

		private DirectLookupBindingSetIteration(DirectLookupKey key, CloseableIteration<? extends Statement> source,
				BindingSet bindings, BiConsumer<MutableBindingSet, Statement> converter) {
			this.key = key;
			this.source = source;
			indexReporter = source instanceof IndexReportingIterator reporter ? reporter : null;
			this.bindings = bindings;
			this.converter = converter;
		}

		@Override
		public boolean hasNext() {
			if (isClosed()) {
				return false;
			}
			try {
				if (source.hasNext()) {
					return true;
				}
				// Some sources signal interruption by returning false.
				List<Statement> completed = Thread.currentThread().isInterrupted() ? null : cacheCandidate;
				close();
				if (completed != null && !cancellationRequested) {
					putCachedDirectLookup(key, List.copyOf(completed));
				}
				return false;
			} catch (RuntimeException | Error failure) {
				ExternalValuePreparation.closeWithSuppressed(this, failure);
				throw failure;
			}
		}

		@Override
		public BindingSet next() {
			if (isClosed()) {
				throw new NoSuchElementException();
			}
			try {
				Statement statement = source.next();
				BindingSet result = bindings;
				if (converter != null) {
					MutableBindingSet converted = context.createBindingSet(bindings);
					converter.accept(converted, statement);
					result = converted;
				}
				if (cacheCandidate != null) {
					if (cacheCandidate.size() == DIRECT_LOOKUP_CACHE_MAX_STATEMENTS) {
						cacheCandidate = null;
					} else {
						if (cacheCandidate.isEmpty()) {
							cacheCandidate = new ArrayList<>(DIRECT_LOOKUP_CACHE_MAX_STATEMENTS);
						}
						cacheCandidate.add(statement);
					}
				}
				return result;
			} catch (RuntimeException | Error failure) {
				ExternalValuePreparation.closeWithSuppressed(this, failure);
				throw failure;
			}
		}

		@Override
		protected void handleClose() {
			cacheCandidate = null;
			source.close();
		}

		@Override
		public boolean requestCancellation() {
			cancellationRequested = true;
			return !isClosed() && CooperativeCancellation.forward(source);
		}

		@Override
		public String getIndexName() {
			return indexReporter == null ? "" : indexReporter.getIndexName();
		}

		@Override
		public long getSourceRowsScannedActual() {
			return indexReporter == null ? -1 : indexReporter.getSourceRowsScannedActual();
		}

		@Override
		public long getSourceRowsMatchedActual() {
			return indexReporter == null ? -1 : indexReporter.getSourceRowsMatchedActual();
		}

		@Override
		public long getSourceRowsFilteredActual() {
			return indexReporter == null ? -1 : indexReporter.getSourceRowsFilteredActual();
		}
	}

	private static final class RepeatedBindingSetIteration implements CloseableIteration<BindingSet> {

		private final BindingSet bindings;
		private long remaining;
		private boolean closed;

		private RepeatedBindingSetIteration(long repeatCount, BindingSet bindings) {
			this.remaining = repeatCount;
			this.bindings = bindings;
		}

		@Override
		public boolean hasNext() throws QueryEvaluationException {
			return !closed && remaining > 0;
		}

		@Override
		public BindingSet next() throws QueryEvaluationException {
			if (!hasNext()) {
				throw new NoSuchElementException();
			}
			remaining--;
			return bindings;
		}

		@Override
		public void remove() throws QueryEvaluationException {
			throw new UnsupportedOperationException();
		}

		@Override
		public void close() throws QueryEvaluationException {
			closed = true;
			remaining = 0;
		}
	}

	private static final class MetricsReportingFilterIteration extends FilterIteration<Statement>
			implements IndexReportingIterator {

		private final CloseableIteration<? extends Statement> iteration;
		private final Predicate<Statement> filter;
		private long locallyMatchedRows;
		private long locallyFilteredRows;

		private MetricsReportingFilterIteration(CloseableIteration<? extends Statement> iteration,
				Predicate<Statement> filter) {
			super(iteration);
			this.iteration = iteration;
			this.filter = filter;
		}

		@Override
		protected boolean accept(Statement object) throws QueryEvaluationException {
			boolean accepted = filter.test(object);
			if (accepted) {
				locallyMatchedRows++;
			} else {
				locallyFilteredRows++;
			}
			return accepted;
		}

		@Override
		protected void handleClose() {
			// no-op
		}

		@Override
		public String getIndexName() {
			IndexReportingIterator metrics = indexReporter();
			return metrics == null ? "" : metrics.getIndexName();
		}

		@Override
		public long getSourceRowsScannedActual() {
			IndexReportingIterator metrics = indexReporter();
			if (metrics != null) {
				long sourceRowsScannedActual = metrics.getSourceRowsScannedActual();
				if (sourceRowsScannedActual >= 0) {
					return sourceRowsScannedActual;
				}
			}
			long locallySeenRows = locallyMatchedRows + locallyFilteredRows;
			return locallySeenRows > 0 ? locallySeenRows : -1;
		}

		@Override
		public long getSourceRowsMatchedActual() {
			IndexReportingIterator metrics = indexReporter();
			if (metrics != null) {
				long sourceRowsMatchedActual = metrics.getSourceRowsMatchedActual();
				if (sourceRowsMatchedActual >= 0) {
					return Math.max(0L, sourceRowsMatchedActual - locallyFilteredRows);
				}
			}
			long locallySeenRows = locallyMatchedRows + locallyFilteredRows;
			return locallySeenRows > 0 ? locallyMatchedRows : -1;
		}

		@Override
		public long getSourceRowsFilteredActual() {
			IndexReportingIterator metrics = indexReporter();
			if (metrics != null) {
				long sourceRowsFilteredActual = metrics.getSourceRowsFilteredActual();
				if (sourceRowsFilteredActual >= 0) {
					return sourceRowsFilteredActual + locallyFilteredRows;
				}
			}
			long locallySeenRows = locallyMatchedRows + locallyFilteredRows;
			return locallySeenRows > 0 ? locallyFilteredRows : -1;
		}

		private IndexReportingIterator indexReporter() {
			return iteration instanceof IndexReportingIterator ? (IndexReportingIterator) iteration : null;
		}
	}

	/**
	 * We need to test every binding with hasBinding etc. as these are not guaranteed to be equivalent between calls of
	 * evaluate(bs).
	 * <p>
	 * Each conversion kind is special cased in with a specific method.
	 *
	 * @return a converter from statement into MutableBindingSet
	 */
	private static BiConsumer<MutableBindingSet, Statement> makeConverter(QueryEvaluationContext context, Var s,
			Var p, Var o, Var c) {

		if (s != null && !s.isConstant()) {
			if (p != null && !p.isConstant()) {
				if (o != null && !o.isConstant()) {
					if (c != null && !c.isConstant()) {
						return StatementConvertor.spoc(context, s, p, o, c);
					} else {
						return StatementConvertor.spo(context, s, p, o);
					}
				} else if (c != null && !c.isConstant()) {
					return StatementConvertor.spc(context, s, p, c);
				} else {
					return StatementConvertor.sp(context, s, p);
				}
			} else if (o != null && !o.isConstant()) {
				if (c != null && !c.isConstant()) {
					return StatementConvertor.soc(context, s, o, c);
				} else {
					return StatementConvertor.so(context, s, o);
				}
			} else if (c != null && !c.isConstant()) {
				return StatementConvertor.sc(context, s, c);
			} else {
				return StatementConvertor.s(context, s);
			}
		} else if (p != null && !p.isConstant()) {
			if (o != null && !o.isConstant()) {
				if (c != null && !c.isConstant()) {
					return StatementConvertor.poc(context, p, o, c);
				} else {
					return StatementConvertor.po(context, p, o);
				}
			} else if (c != null && !c.isConstant()) {
				return StatementConvertor.pc(context, p, c);
			} else {
				return StatementConvertor.p(context, p);
			}
		} else if (o != null && !o.isConstant()) {
			if (c != null && !c.isConstant()) {
				return StatementConvertor.oc(context, o, c);
			} else {
				return StatementConvertor.o(context, o);
			}
		} else if (c != null && !c.isConstant()) {
			return StatementConvertor.c(context, c);
		}

		return (a, b) -> {
		};

	}

	private static BiConsumer<MutableBindingSet, Statement> makeConvertStatementConverter(
			QueryEvaluationContext context,
			Var s, Var p, Var o, Var c) {

		if (s != null && !s.isConstant()) {
			if (p != null && !p.isConstant()) {
				if (o != null && !o.isConstant()) {
					if (c != null && !c.isConstant()) {
						return StatementConvertorWithoutBindingChecks.spoc(context, s, p, o, c);
					} else {
						return StatementConvertorWithoutBindingChecks.spo(context, s, p, o);
					}
				} else if (c != null && !c.isConstant()) {
					return StatementConvertorWithoutBindingChecks.spc(context, s, p, c);
				} else {
					return StatementConvertorWithoutBindingChecks.sp(context, s, p);
				}
			} else if (o != null && !o.isConstant()) {
				if (c != null && !c.isConstant()) {
					return StatementConvertorWithoutBindingChecks.soc(context, s, o, c);
				} else {
					return StatementConvertorWithoutBindingChecks.so(context, s, o);
				}
			} else if (c != null && !c.isConstant()) {
				return StatementConvertorWithoutBindingChecks.sc(context, s, c);
			} else {
				return StatementConvertorWithoutBindingChecks.s(context, s);
			}
		} else if (p != null && !p.isConstant()) {
			if (o != null && !o.isConstant()) {
				if (c != null && !c.isConstant()) {
					return StatementConvertorWithoutBindingChecks.poc(context, p, o, c);
				} else {
					return StatementConvertorWithoutBindingChecks.po(context, p, o);
				}
			} else if (c != null && !c.isConstant()) {
				return StatementConvertorWithoutBindingChecks.pc(context, p, c);
			} else {
				return StatementConvertorWithoutBindingChecks.p(context, p);
			}
		} else if (o != null && !o.isConstant()) {
			if (c != null && !c.isConstant()) {
				return StatementConvertorWithoutBindingChecks.oc(context, o, c);
			} else {
				return StatementConvertorWithoutBindingChecks.o(context, o);
			}
		} else if (c != null && !c.isConstant()) {
			return StatementConvertorWithoutBindingChecks.c(context, c);
		}

		return (a, b) -> {
		};
	}

	private static Predicate<Statement> andThen(Predicate<Statement> pred, Predicate<Statement> and) {
		if (pred == null) {
			return and;
		}
		return pred.and(and);
	}

